<?php
// Profile actual production read methods and endpoint SQL; no performance patch here.
require_once __DIR__.'/dashboard-profile.php';
require_once __DIR__.'/../services/MessageService.php';
require_once __DIR__.'/../services/LearningWorkspaceService.php';
$db=new PDO(getenv('CHAT_PERF_DSN'),'root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_STATEMENT_CLASS=>[DashboardStatement::class]]);
(new ReflectionProperty(Database::class,'instance'))->setValue(null,$db);
$db->exec("ALTER TABLE users ADD avatar_url TEXT,ADD is_verified INT DEFAULT 0;ALTER TABLE messages ADD content_type VARCHAR(20) DEFAULT 'text',ADD parent_id BIGINT NULL,ADD is_edited INT DEFAULT 0,ADD reaction_count INT DEFAULT 0;CREATE TABLE message_reactions(message_id BIGINT,user_id BIGINT,emoji VARCHAR(20));ALTER TABLE study_room_sessions ADD channel_id INT DEFAULT 1;CREATE TABLE channel_members(channel_id INT,user_id BIGINT);CREATE TABLE moderation_actions(id INT,server_id INT,target_user_id BIGINT,action_type VARCHAR(20),is_active INT,expires_at DATETIME);CREATE TABLE calendar_events(id INT,user_id BIGINT,title TEXT,description TEXT,event_type VARCHAR(20),starts_at DATETIME,ends_at DATETIME);INSERT INTO student_notes SELECT seq+1,1,CONCAT('Note ',seq),'Synthetic note',NOW(),1 FROM seq_1_to_199;INSERT INTO uploaded_files SELECT seq+1,'fixture','fixture','/synthetic',100,'text/plain',1,1,1,NOW(),NULL FROM seq_1_to_199;
CREATE TABLE dm_conversations(id BIGINT PRIMARY KEY,user_a BIGINT,user_b BIGINT,last_message TEXT,last_msg_at DATETIME,created_at DATETIME);CREATE TABLE dm_messages(id BIGINT PRIMARY KEY,conversation_id BIGINT,sender_id BIGINT,body TEXT,is_deleted INT DEFAULT 0,created_at DATETIME,INDEX idx_conv(conversation_id,created_at));CREATE TABLE dm_reads(user_id BIGINT,conversation_id BIGINT,last_read_at DATETIME,PRIMARY KEY(user_id,conversation_id));
INSERT INTO dm_conversations SELECT seq,1,seq+1,'Synthetic',DATE_SUB(NOW(),INTERVAL seq SECOND),NOW() FROM seq_1_to_50;INSERT INTO dm_messages SELECT seq,1+MOD(seq-1,50),IF(MOD(seq,2)=0,1,2+MOD(seq-1,50)),'Synthetic',0,DATE_SUB(NOW(),INTERVAL seq SECOND) FROM seq_1_to_25000");
function profile(callable $read):array{DashboardProfile::$queries=[];$t=hrtime(true);$data=$read();$sql=DashboardProfile::$queries;foreach($sql as$q)if(!$q['success'])throw new RuntimeException('Read failed');return ['elapsed_ms'=>(hrtime(true)-$t)/1e6,'queries'=>$sql,'rows'=>count($data)];}
$service=new MessageService();$first=$service->getMessages(1,1);if(count($first)!==50)throw new RuntimeException('History fixture missing rows');
$out=['history_first'=>profile(fn()=>$service->getMessages(1,1)),'history_before'=>profile(fn()=>$service->getMessages(1,1,(int)$first[0]['id'])),'history_after'=>profile(fn()=>$service->getMessages(1,1,null,50,(int)$first[0]['id']))];
foreach(['student'=>[1,false,0],'facilitator'=>[900,true,1]]as$kind=>$args)$out['workspace_'.$kind]=profile(function()use($db,$args){$d=(new LearningWorkspaceService($db))->data(...$args);foreach($d as$key=>$source)if($key!=='limits'&&!$source['available'])throw new RuntimeException('Workspace fixture unavailable '.$key);return $d;});
$source=file_get_contents(__DIR__.'/../API/dm/get-conversations.php');if(!preg_match('/prepare\("(.*?)"\);/s',$source,$match))throw new RuntimeException('Actual endpoint SQL not found');$sql=$match[1];$args=array_fill_keys([':me2',':me3',':me4',':me5',':me6'],1);
$out['dm_conversation_list']=profile(function()use($db,$sql,$args){$q=$db->prepare($sql);$q->execute($args);return $q->fetchAll(PDO::FETCH_ASSOC);});
echo json_encode($out,JSON_THROW_ON_ERROR);
